"""Publish r11 outline remodeling, source comparisons and saved geometry evidence."""
from pathlib import Path
import json,hashlib,shutil,re,subprocess
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/art/creature-models/2026-10-14/rift-titan-notched-r11'
OLD=ROOT/'docs/art/creature-models/2026-10-13/rift-titan-layered-r10'
row=json.loads((OUT/'refinement-metrics.json').read_text());ID=row['id'];previous='underworld-boss-rift-titan-layered-r10'
checks={n:json.loads((OUT/(n+'.json')).read_text()) for n in ('verification','attachment-verification','closing-face-verification','crystal-face-verification','thorax-face-verification','side-orientation','notch-verification')}
assert row['triangles']==checks['verification']['triangles']==1800
assert checks['attachment-verification']['result']=='PASS' and checks['attachment-verification']['endpoints']==76
for n,total in [('closing-face-verification',8064),('crystal-face-verification',14112),('thorax-face-verification',2016)]:assert checks[n]['result']=='PASS' and checks[n]['sampled_points']==total and checks[n]['poses']==36 and checks[n]['max_outside_distance_metres']==0
assert checks['notch-verification']['result']=='PASS' and len(checks['notch-verification']['remodeled_components'])==19 and checks['notch-verification']['triangles_transferred']==32
sha=hashlib.sha256((ROOT/row['source']).read_bytes()).hexdigest();assert checks['verification']['source_sha256']==checks['side-orientation']['source_sha256']==sha and checks['side-orientation']['camera_direction'][0]<0
detail=json.loads((OUT/'before/detail-provenance.json').read_text());assert detail['source_sha256']==hashlib.sha256((ROOT/detail['source']).read_bytes()).hexdigest()
views=('three-quarter','front','side','front-clay','side-clay','side-reference')
for view in views:shutil.copy2(OLD/(previous+'--'+view+'.png'),OUT/'before'/(previous+'--'+view+'.png'))
for p in ('concept-front.png','concept-side.png'):shutil.copy2(OLD/p,OUT/p)
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rift Titan — chipped stone contours r11</title>
<style>body{{background:#14191c;color:#e4e5df;font:16px system-ui;max-width:1500px;margin:auto;padding:24px}}p{{line-height:1.6;max-width:1150px}}a{{color:#9ccdda}}img{{width:100%;object-fit:contain;background:#171e22}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}.reference img{{height:650px}}figure{{margin:0}}figcaption{{padding:8px;color:#bbc5c6}}button{{background:#283840;color:#e4e5df;border:1px solid #60747a;padding:8px 14px;margin:5px;cursor:pointer}}@media(max-width:800px){{.pair{{grid-template-columns:1fr}}.reference img{{height:500px}}}}</style>
<h1>Rift Titan — chipped stone contours r11</h1>
<p>The two head halves and six shoulder plates have actual stepped outer contours, replacing long unbroken edges. Four central forearm/shin plates have inward notches and angular shell faces. Eight triangles from the rear head plate and twenty-four from simpler palm, foot and pelvis surfaces are reassigned to the visible head/shoulder outlines. All nineteen remodeled stone shells remain closed. These are outline and topology changes; the r10 surface style is retained and re-baked for the revised shapes.</p>
<p><strong>1,800 triangles · native Stone Golem 1,200 · 1.500× · cap 1,800.</strong> One mesh/material, four packed 512px maps, eight original bone identities and seven actions. Both torso rings, the forward crest rake, limb crystal growths and original arm-root blends remain.</p>
<h2>Previous and current — matched views</h2><div><button data-view="crown-detail">Head and shoulder close-up</button><button data-view="three-quarter">Whole surface</button><button data-view="front">Front surface</button><button data-view="side">True side surface</button><button data-view="front-clay">Front clay</button><button data-view="side-clay">True side clay</button><button data-view="side-reference">Angled side</button></div><div class="pair"><figure><img id="before" src="before/{previous}--crown-detail.png" alt="Preserved r10 head and shoulders"><figcaption>Previous r10 — saved source re-rendered with the close-up camera</figcaption></figure><figure><img id="after" src="{ID}--crown-detail.png" alt="Current r11 head and shoulders"><figcaption>Current r11 — stepped head edges and chipped mantle</figcaption></figure></div>
<h2>Front reference</h2><div class="pair reference"><figure><img src="concept-front.png" alt="Concept front"><figcaption>Adopted concept front</figcaption></figure><figure><img src="{ID}--front-reference.png" alt="Current front clay"><figcaption>Current front clay — outline chips remain visible without the material</figcaption></figure></div>
<h2>Left-facing side reference</h2><div class="pair reference"><figure><img src="concept-side.png" alt="Concept side"><figcaption>Concept — front/head left, back right</figcaption></figure><figure><img src="{ID}--side-reference-clay.png" alt="Current left-facing clay"><figcaption>Current angled side; true profile available above with the same facing</figcaption></figure></div>
<h2>Adopted concept</h2><img src="../../../creature-concepts/2026-10-03/the-rift-titan.png" alt="Full source concept sheet">
<h2>Native donor quality and cost reference</h2><div class="pair"><figure><img src="../../2026-10-04/detail-r2/donor-StoneGolem--three-quarter.png" alt="Native Stone Golem reference"><figcaption>Native Stone Golem — 1,200 triangles; visual quality reference</figcaption></figure><figure><img src="{ID}--three-quarter.png" alt="Current Rift Titan surface"><figcaption>Current Rift Titan — 1,800 triangles; concept and native art acceptance still pending</figcaption></figure></div>
<p>The first attachment audit caught an arm closing face bridging a new shoulder notch. The full buried six-vertex section was contracted toward a common interior anchor; a left upper-thorax section received the same correction. The repaired closing faces, not merely their boundaries, pass the saved animated checks.</p>
<p>All 76 support groups pass rest and 35 sampled action poses. Basal-face interiors/edges pass 8,064 arm/digit, 14,112 crystal and 2,016 upper-thorax samples across the same 36 poses, with zero measured outside distance. Saved manifold/finite/nondegenerate geometry, weights, retained rig/actions, packed maps and portable skinned export pass. Native every-frame deformation and live performance remain pending.</p>
<p>This continues the 85% concept-match target; it is not a claim that the target is reached. More individual fragmentation, crest debris, core density and controlled weathering remain. The original planning range is 8–12 substantial passes after r10; r11 is the first checkpoint, with a reassessment after r12. <a href="../../RIFT-TITAN-REFINEMENT-OUTLOOK.md">Progress and outlook</a>. Adequately reworked boss tally remains 1/6.</p>
<p><a href="../../../../../{row['source']}">Editable Blender model</a> · <a href="{ID}.glb">Skinned export</a> · <a href="{ID}--attack.png">Attack pose</a> · <a href="notch-authoring.json">Changes and triangle transfers</a> · <a href="notch-verification.json">Nineteen closed shells</a> · <a href="verification.json">Mesh/export checks</a> · <a href="attachment-verification.json">Support checks</a> · <a href="closing-face-verification.json">Arm/digit basal faces</a> · <a href="crystal-face-verification.json">Crystal basal faces</a> · <a href="thorax-face-verification.json">Upper-thorax basal faces</a> · <a href="side-orientation.json">Camera direction</a> · <a href="provenance.json">Source provenance</a></p>
<script>document.querySelectorAll('button[data-view]').forEach(b=>b.onclick=()=>{{document.getElementById('before').src='before/{previous}--'+b.dataset.view+'.png';document.getElementById('after').src='{ID}--'+b.dataset.view+'.png';}});</script></html>'''
sources=['tools/rift_titan_r4_base.py','tools/rift_titan_primary_layout.py','tools/rift_titan_rock_facets.py','tools/rift_titan_wrapped_torso.py','tools/rift_titan_silhouette_fit.py','tools/rift_titan_joint_silhouette.py','tools/rift_titan_crystal_limbs.py','tools/rift_titan_crown_profile.py','tools/rift_titan_layered_weathering.py','tools/rift_titan_notched_stone.py','tools/refine-first-bloom.py','tools/refine-rift-titan-notched-r11.py','tools/review-rift-titan-notched-r11.py','tools/review-rift-titan-notched-before-r11.py','tools/verify-rift-titan-notched-r11.py','tools/publish-rift-titan-notched-r11.py',row['source'],detail['source'],'docs/art/creature-concepts/2026-10-03/the-rift-titan.png','docs/art/creature-models/RIFT-TITAN-REFINEMENT-OUTLOOK.md']
(OUT/'provenance.json').write_text(json.dumps(dict(base_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in sources},scope='r10 geometry continued with local outline topology redistribution; retained owned surfaces and rig',acceptance='unaccepted; 85% target not claimed; tally 1/6'),indent=2)+'\n',encoding='utf-8')
(OUT/'gallery.html').write_text(html,encoding='utf-8')
for target in re.findall(r'(?:href|src)="([^"]+)"',html):assert (OUT/target).resolve().is_file(),target
for view in (*views,'crown-detail'):assert (OUT/(ID+'--'+view+'.png')).is_file() and (OUT/'before'/(previous+'--'+view+'.png')).is_file()
print('VERIFIED r11 gallery, source hashes, matched close-up, left-facing comparisons, 76 supports and 1800 triangle cap')
